// Provenance: original
//
// TimeZoneNames prints javatimezone_data.go: the time zones of the reference
// JVM (TimeZone.getAvailableIDs) with the zone whose rules they use and their
// display names in the en_US locale, which %date prints for the z pattern.
//
// Regenerate in the reference image with:
//
//	go test -tags upstreamgen -run TestGenerateTimeZoneNames ./internal/tim

import java.util.Locale;
import java.util.TimeZone;

public class TimeZoneNames {

	public static void main(String[] args) {
		final StringBuilder sb = new StringBuilder();
		sb.append("// SPDX-License-Identifier: MIT\n");
		sb.append("// Provenance: original\n");
		sb.append("// Code generated by testdata/upstream/TimeZoneNames.java with ")
				.append(System.getProperty("java.vm.name")).append(' ')
				.append(System.getProperty("java.version")).append(". DO NOT EDIT.\n\n");
		sb.append("package tim\n\n");
		sb.append("// javaTimeZoneData lists the zones of TimeZone.getAvailableIDs, one per\n");
		sb.append("// line: id|rules|short standard name|long standard name|short daylight\n");
		sb.append("// name|long daylight name. rules is empty when the zone uses the rules of\n");
		sb.append("// the IANA zone with the same id, else an IANA zone, a fixed offset or a\n");
		sb.append("// SystemV zone.\n");
		sb.append("const javaTimeZoneData = `\n");
		for (String id : TimeZone.getAvailableIDs()) {
			final TimeZone tz = TimeZone.getTimeZone(id);
			String rules = tz.toZoneId().getId();
			if (rules.equals(id))
				rules = "";
			if (id.startsWith("SystemV/"))
				rules = id;
			sb.append(id).append('|').append(rules);
			sb.append('|').append(tz.getDisplayName(false, TimeZone.SHORT, Locale.US));
			sb.append('|').append(tz.getDisplayName(false, TimeZone.LONG, Locale.US));
			sb.append('|').append(tz.getDisplayName(true, TimeZone.SHORT, Locale.US));
			sb.append('|').append(tz.getDisplayName(true, TimeZone.LONG, Locale.US));
			sb.append('\n');
		}
		sb.append("`\n");
		System.out.print(sb);
	}
}
